An image conversion service takes a user-supplied image filename and passes it to an external command. The application builds a command string by concatenating the filename directly without escaping shell metacharacters.

String filename = request.getParameter("image");
String cmd = "convert input.jpg -resize 800x600 " + filename;
Process process = Runtime.getRuntime().exec(cmd);
OutputStream out = process.getOutputStream();
out.write(imageData);
out.close();

A backup utility constructs a tar command from user input to archive files. The application uses sprintf to format a shell command with untrusted input, then passes it to system().

#include <stdio.h>
#include <stdlib.h>
char backup_file[256];
scanf("%s", backup_file);
char command[512];
sprintf(command, "tar czf backup.tar.gz %s", backup_file);
int status = system(command);
if (status == 0) {
    printf("Backup complete\n");
}

A report generator exports data using a user-supplied filename and passes it to a shell command. The application concatenates user input into a command string and executes it via popen().

#include <iostream>
#include <cstdlib>
using namespace std;
string reportname = getUserInput();
string cmd = "export_data --output " + reportname;
FILE* pipe = popen(cmd.c_str(), "r");
char buffer[256];
while (fgets(buffer, sizeof(buffer), pipe) != NULL) {
    cout << buffer;
}

A video processing service builds a command string from user-supplied parameters. The application concatenates filename and quality arguments into a shell command without sanitization.

String videoFile = request.getParameter("file");
String cmd = "ffmpeg -i " + videoFile + " -q:v 18 output.mp4";
Process process = Runtime.getRuntime().exec(cmd);
int exitCode = process.waitFor();
if (exitCode == 0) {
    return true;
}
return false;

A plugin loader executes external programs based on user-supplied plugin names. The application constructs a command using gets() to read untrusted input and passes it to execvp().

#include <stdio.h>
#include <unistd.h>
char plugin_name[256];
gets(plugin_name);
char command[512];
sprintf(command, "./plugins/%s", plugin_name);
char *args[] = {command, NULL};
execvp(command, args);

A text processing service accepts filenames for document conversion. The application directly concatenates the filename into a shell command for PDF generation.

#include <iostream>
#include <cstdlib>
#include <string>
using namespace std;
string inputFile = getParameterFromWeb("inputfile");
string cmd = "pdflatex " + inputFile + " -output-directory=/tmp";
int result = system(cmd.c_str());
if (result == 0) {
    moveFile("/tmp/output.pdf", "/var/www/output.pdf");
}

An email notification service constructs shell commands from user-supplied email and subject parameters. The application concatenates these parameters into a mail command without escaping.

String recipient = request.getParameter("email");
String subject = request.getParameter("subject");
String cmd = "mail -s " + subject + " " + recipient;
Process p = Runtime.getRuntime().exec(cmd);
p.getOutputStream().write(messageBody.getBytes());
p.waitFor();

An archive extraction utility processes user-supplied filenames without validation. The application constructs a tar command by appending user input directly to the command string.

#include <stdio.h>
#include <string.h>
char archive[256];
scanf("%s", archive);
char command[512];
sprintf(command, "tar xzf %s", archive);
int ret = system(command);
printf("Extraction exit code: %d\n", ret);

A PDF generation service takes user input for document creation and passes it to an external tool. The application builds a command string by concatenating the document path without escaping.

String docPath = request.getParameter("document");
String cmd = "wkhtmltopdf " + docPath + " output.pdf";
Process process = Runtime.getRuntime().exec(cmd);
File output = new File("output.pdf");
if (output.exists()) {
    return sendFile(output);
}

A cache cleaning utility accepts user-provided cache directory paths. The application constructs a shell command that directly incorporates the user path.

#include <iostream>
#include <cstdlib>
using namespace std;
string cachePath = getUserInput();
string cmd = "rm -rf " + cachePath + "/*";
FILE* proc = popen(cmd.c_str(), "w");
if (proc) {
    pclose(proc);
    cout << "Cache cleared" << endl;
}

A file download endpoint constructs file paths from user input using os.path.join(). The application fails to validate that the resolved path remains within the intended download directory.

import os
from flask import request, send_file
filename = request.args.get('file')
filepath = os.path.join('/var/www/downloads', filename)
if os.path.exists(filepath):
    return send_file(filepath)
else:
    return "File not found", 404

A backup restoration service accepts user-provided restore paths. The application opens a FileInputStream using the user-supplied path without checking directory boundaries.

import java.io.FileInputStream;
String backupFile = request.getParameter("backup");
String restorePath = "/backups/" + backupFile;
try {
    FileInputStream fis = new FileInputStream(restorePath);
    byte[] data = new byte[1024];
    fis.read(data);
    restoreFromData(data);
} catch (IOException e) {
    log.error("Restore failed", e);
}

A configuration reader loads config files from user-supplied paths. The application uses sprintf() to construct the path and opens it with fopen() without validating the resolved path.

#include <stdio.h>
char config_name[256];
scanf("%s", config_name);
char config_path[512];
sprintf(config_path, "/etc/myapp/%s", config_name);
FILE *f = fopen(config_path, "r");
char line[256];
while (fgets(line, sizeof(line), f)) {
    parseLine(line);
}

A log viewer displays logs specified by user-provided names. The application concatenates the name to a base directory path and opens it with ifstream without canonicalization.

#include <iostream>
#include <fstream>
using namespace std;
string logname = getUserRequest();
string logpath = "/var/log/app/" + logname;
ifstream logfile(logpath.c_str());
string line;
while (getline(logfile, line)) {
    cout << line << endl;
}

A file upload service stores files based on user-provided names without path validation. The application constructs an upload path by concatenating user input directly.

import java.io.FileOutputStream;
String filename = request.getParameter("name");
String uploadPath = "/uploads/" + filename;
try {
    FileOutputStream fos = new FileOutputStream(uploadPath);
    fos.write(fileData);
    fos.close();
} catch (IOException e) {
    return "Upload failed";
}

A document server serves files based on user requests for document IDs. The application constructs a file path by appending user input to a base directory without path validation.

#include <stdio.h>
char doc_id[256];
scanf("%s", doc_id);
char filepath[512];
sprintf(filepath, "/documents/%s", doc_id);
FILE *f = fopen(filepath, "r");
if (f) {
    serveFile(f);
    fclose(f);
}

A cache manager retrieves cached data using user-provided keys. The application constructs a cache file path by concatenating the key without validation.

#include <iostream>
#include <fstream>
using namespace std;
string cache_key = request.getParameter("key");
string cache_file = "/cache/" + cache_key;
ifstream cachefile(cache_file.c_str());
string cached_data((istreambuf_iterator<char>(cachefile)),
                   istreambuf_iterator<char>());
return cached_data;

A configuration loader reads config files by user-specified name without path canonicalization. The application constructs a File object using user input concatenated to a base path.

import java.util.Properties;
import java.io.FileInputStream;
String configName = request.getParameter("config");
File configFile = new File("/config/" + configName);
try {
    FileInputStream fis = new FileInputStream(configFile);
    Properties props = new Properties();
    props.load(fis);
    fis.close();
} catch (IOException e) {
    log.error("Config load failed", e);
}

A report generator creates reports with user-supplied filenames. The application constructs a file path by appending user input to a base directory path.

#include <stdio.h>
char report_id[256];
scanf("%s", report_id);
char report_path[512];
sprintf(report_path, "/reports/%s.txt", report_id);
FILE *f = fopen(report_path, "w");
if (f) {
    fprintf(f, "%s", report_content);
    fclose(f);
}

A static file server serves files from user-supplied URL paths. The application appends the path info directly to a base directory without normalization or validation.

import java.io.FileInputStream;
String requestedFile = request.getPathInfo();
String filepath = "/var/www/public" + requestedFile;
try {
    FileInputStream fis = new FileInputStream(filepath);
    response.setContentType("application/octet-stream");
    response.getOutputStream().write(fis.readAllBytes());
    fis.close();
} catch (IOException e) {
    response.setStatus(404);
}

A database backup utility accepts user-provided database names for backup creation. The application constructs a backup file path by concatenating the database name.

#include <iostream>
#include <fstream>
using namespace std;
string db_name = getInputFromUser();
string backup_path = "/backups/" + db_name + ".sql";
ofstream backupfile(backup_path.c_str());
backupfile << "-- Database backup for " << db_name << endl;
backupfile << getBackupData(db_name);
backupfile.close();
